<section class="flex flex-col mt-[50vh] min-h-screen mx-10">
    <div class="border-b border-b-black/35 pb-5">
        <h2 class="text-8xl font-dm font-bold tracking-[1%] leading-[100%] text-[#031831]">
            Spájame<br/> poznanie s praxou.
        </h2>
    </div>
    <div class="flex justify-start mt-5">
        <span class="font-semibold w-[10%] shrink-0">
            02 - 02
        </span>

        <div class="flex flex-col gap-5 w-full ml-[40%]">
            <div class="flex gap-10">
                <p class="w-[350px] shrink-0 text-[#031831] text-[16.5px] leading-[130%]">
                    SmartLab vznikol ako spoločná iniciatíva Univerzity sv. Cyrila a Metoda v Trnave a mesta Trnava zameraná na podporu vzdelávania, aplikovaného výskumu a spolupráce medzi akademickou sférou, verejným sektorom a odbornou praxou.
                </p>

                <p class="w-[350px] shrink-0 text-[#031831] text-[16.5px] leading-[130%]">
                    Cieľom SmartLabu je prispieť k rozvoju digitálnych kompetencií, zvýšeniu záujmu o štúdium informatiky a vytváraniu priestoru pre inovácie a technologický rozvoj.
                </p>
            </div>
        </div>
    </div>
